public static int CompareNumbers(List<int> a, List<int> b) {
    for (int i = 0; i < Math.Min(a.Count, b.Count); i++) {
        int c = a[i].CompareTo(b[i]);
        if (c != 0)
            return c;
    }
    return a.Count.CompareTo(b.Count);
